import document from "../generated/openapi.json";

/**
 * The OpenAPI document for `/api/v1`, served as committed.
 *
 * It is generated by `scripts/generate-openapi.mjs` from the transport
 * metadata in `@requestport/domain`, and a test fails when the committed copy
 * is stale; nothing here builds or edits it. It names no server: its paths
 * carry `/api/v1`, so they resolve against the origin that served it.
 */
export function GET() {
  return Response.json(document);
}
